/**
 * Debug script - Check why some sources return 0 events
 */

const axios = require('axios');
const cheerio = require('cheerio');

async function debugSource(name, url) {
  console.log('\n=== DEBUG: ' + name + ' ===');
  try {
    const resp = await axios.get(url, { timeout: 15000, headers: { 'User-Agent': 'EventPulse/1.0' } });
    console.log('Status:', resp.status);

    const html = resp.data;
    const $ = cheerio.load(html);

    // Check for JSON-LD
    const ldScripts = $('script[type="application/ld+json"]').length;
    console.log('JSON-LD scripts found:', ldScripts);


